-- HWAY Payroll Supabase schema
-- Run this in the Supabase SQL editor for project bgobasrlbmxnzflnfzch,
-- or with psql using the Supabase Postgres connection string.

begin;

create table if not exists public."Employees" (
    "Id" integer generated by default as identity,
    "Employee #" character varying(50) not null,
    "First Name" character varying(100) not null,
    "Last Name" character varying(100) not null,
    "SIN" character varying(20),
    "Address" character varying(300),
    "City" character varying(100),
    "Province" character varying(50),
    "Postal Code" character varying(20),
    "E-Mail Address" character varying(200),
    "RpNumber" text not null,
    constraint "PK_Employees" primary key ("Id")
);

create table if not exists public."Employers" (
    "Id" integer generated by default as identity,
    "RP#" character varying(50) not null,
    "Employer Name" character varying(200) not null,
    "Address" character varying(300),
    "City" character varying(100),
    "Postal code" character varying(20),
    "Employer Group" character varying(100),
    "Fee" numeric(18,2) not null default 0,
    constraint "PK_Employers" primary key ("Id")
);

create table if not exists public."PayrollRecords" (
    "Id" integer generated by default as identity,
    "Employee #" character varying(50) not null,
    "RP#" character varying(50) not null,
    "Employees Name" character varying(200) not null,
    "Period" integer not null default 0,
    "Salary" numeric(18,2) not null,
    "Rate" numeric(18,2) not null,
    "R.Hours" numeric(18,2) not null,
    "OV.Hours" numeric(18,2) not null,
    "Public.H" numeric(18,2) not null,
    "S.H Hours" numeric(18,2) not null,
    "Vacation" numeric(18,2) not null,
    "vacation_setting" character varying(20) not null default 'Accumulate',
    "Gross" numeric(18,2) not null,
    "TAX1" numeric(18,2) not null,
    "CPP1" numeric(18,2) not null,
    "CPP2" numeric(18,2) not null,
    "EI" numeric(18,2) not null,
    "Other deduction" numeric(18,2) not null,
    "NET PAY" numeric(18,2) not null,
    "Gross-YTD" numeric(18,2) not null,
    "NET-YTD" numeric(18,2) not null,
    "TAX -YTD" numeric(18,2) not null,
    "CPP1-YTD" numeric(18,2) not null,
    "CPP2-YTD" numeric(18,2) not null,
    "EI-YTD" numeric(18,2) not null,
    "Other Deduction-YTD" numeric(18,2) not null,
    "Vacation -YTD" numeric(18,2) not null,
    "Vacation -YTD-Used" numeric(18,2) not null,
    "Vacation -YTD- Balance" numeric(18,2) not null,
    "Total PD7" numeric(18,2) not null,
    "Hire Date" date,
    constraint "PK_PayrollRecords" primary key ("Id")
);

create table if not exists public."PD7" (
    "RP#" character varying(50) not null,
    "Month" integer not null,
    "Year" integer not null,
    "Fee" numeric(18,2) not null,
    "Gross" numeric(18,2) not null,
    "PD7 Total" numeric(18,2) not null,
    "Active Employees" integer not null,
    "Period" text not null,
    "Transfer" numeric(18,2) not null,
    "Received" numeric(18,2) not null,
    "Fee Check" boolean not null,
    constraint "PK_PD7" primary key ("RP#", "Month", "Year")
);

create unique index if not exists "IX_Employees_Employee #"
    on public."Employees" ("Employee #");

create unique index if not exists "IX_Employers_RP#"
    on public."Employers" ("RP#");

create index if not exists "IX_PayrollRecords_Employee #"
    on public."PayrollRecords" ("Employee #");

create index if not exists "IX_PayrollRecords_RP#"
    on public."PayrollRecords" ("RP#");

do $$
begin
    if not exists (
        select 1
        from pg_constraint
        where conname = 'FK_PayrollRecords_Employees_Employee #'
    ) then
        alter table public."PayrollRecords"
            add constraint "FK_PayrollRecords_Employees_Employee #"
            foreign key ("Employee #")
            references public."Employees" ("Employee #")
            on delete cascade;
    end if;

    if not exists (
        select 1
        from pg_constraint
        where conname = 'FK_PayrollRecords_Employers_RP#'
    ) then
        alter table public."PayrollRecords"
            add constraint "FK_PayrollRecords_Employers_RP#"
            foreign key ("RP#")
            references public."Employers" ("RP#")
            on delete cascade;
    end if;
end $$;

commit;
